using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        List<string> lines = new List<string>
        {
            "این شب، دلهره‌ی غلیظِ شب نیست",
            "این شب، شبِ غلیظِ این شب نیست",
            "امشب مدهِ دیشب نیست",
            "صبحِ شبِ مده، امشب نیست"
        };

        PrintPoem(lines);
    }

    static void PrintPoem(List<string> lines)
    {
        foreach (string line in lines)
        {
            Console.WriteLine(line);
            if (line.Contains("شب"))
            {
                Console.WriteLine("...");
            }
        }
    }
}

