using System;
using System.Collections.Generic;
class Program
{
    static void Main()
    {
        List<string> lines = new List<string>()
        {
            "این شبی که می گم شب نیست",
            "بلکه شبِ منده اون شب نیست",
            "تا شبِ منده دیشب نیست",
            "تَبِ‌یه شبی مُدِ، امشب نیست"
        };
        PrintPoem(lines);
    }
    static void PrintPoem(List<string> lines)
    {
        foreach (string line in lines)
        {
            Console.WriteLine(line);
            if (line.Contains("شبِ"))
            {
                Console.WriteLine("شب نیست");
            }
        }
    }
}
